def document():
    d=Document(); sec=d.sections[0]
    sec.page_width=Inches(8.5);sec.page_height=Inches(11)
    sec.top_margin=sec.bottom_margin=Inches(.7)
    sec.left_margin=sec.right_margin=Inches(.75)
    for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Caption']:
        s=d.styles[name];s.font.name='Arial';s.font.color.rgb=RGBColor(0,0,0)
        s.font.size=Pt({'Title':26,'Subtitle':13,'Heading 1':19,'Heading 2':13,'Caption':9}.get(name,11))
        s.paragraph_format.space_after=Pt(8)
        for border in s.element.xpath('.//w:pBdr'):
            border.getparent().remove(border)
    d.styles['Normal'].paragraph_format.line_spacing=1.13
    sec.header.paragraphs[0].text='ПРИХОД  |  Материалы для Владыки Тихона  |  15 октября 2026'
    sec.header.paragraphs[0].style=d.styles['Caption']
    p=sec.footer.paragraphs[0];p.alignment=2
    p.add_run('Приход  •  ')
    f=OxmlElement('w:fldSimple');f.set(qn('w:instr'),'PAGE');p._p.append(f)
    d.core_properties.author='Проект Приход'
    d.core_properties.subject='Самостоятельное создание и ведение приходских сайтов'
    return d

def para(d,text):d.add_paragraph(text)
def page(d,title,first=False):
    if not first:d.add_page_break()
    d.add_heading(title,0 if first else 1)
def bullets(d,items):
    for s in items:d.add_paragraph(s,style='List Bullet')
def table(d,headers,rows,widths=None):
    t=d.add_table(rows=1,cols=len(headers));t.autofit=False
    for i,h in enumerate(headers):t.rows[0].cells[i].text=h
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row):cells[i].text=str(v)
    for ri,row in enumerate(t.rows):
        trPr=row._tr.get_or_add_trPr()
        if ri==0:
            repeat=OxmlElement('w:tblHeader');trPr.append(repeat)
        for ci,c in enumerate(row.cells):
            if widths:c.width=Inches(widths[ci])
            tcPr=c._tc.get_or_add_tcPr()
            borders=OxmlElement('w:tcBorders')
            for side in ['top','left','bottom','right']:
                edge=OxmlElement('w:'+side);edge.set(qn('w:val'),'single');edge.set(qn('w:sz'),'4');edge.set(qn('w:color'),'D9D9D9');borders.append(edge)
            tcPr.append(borders)
            shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'20374A' if ri==0 else ('F2F5F7' if ri%2==0 else 'FFFFFF'));tcPr.append(shade)
            margins=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                e=OxmlElement('w:'+side);e.set(qn('w:w'),'85');e.set(qn('w:type'),'dxa');margins.append(e)
            tcPr.append(margins)
            for p in c.paragraphs:
                p.paragraph_format.space_after=Pt(3);p.paragraph_format.line_spacing=1.02
                for run in p.runs:
                    run.font.size=Pt(9);run.font.bold=ri==0
                    run.font.color.rgb=RGBColor(255,255,255) if ri==0 else RGBColor(0,0,0)
    return t

def figure(d,path,caption,width=6.8,maxheight=4.9):
    path=ROOT/path if not Path(path).is_absolute() else Path(path)
    im=Image.open(path);w,h=im.size
    display=min(width,maxheight*w/h)
    p=d.add_paragraph();p.alignment=1;p.add_run().add_picture(str(path),width=Inches(display))
    d.add_paragraph(caption,style='Caption')

def crop(src,name,ratio=.53):
    im=Image.open(ROOT/src);w,h=im.size
    # Remove the WordPress admin toolbar and show the useful first screen.
    top=round(w*.022)
    im.crop((0,top,w,min(h,top+int(w*ratio)))).save(IMG/name)
    return IMG/name

